  "plans.mobileIncludedNote": "تتضمن خطتا الموقع الإلكتروني كلتاهما الرفيق على الهاتف، فلا يدفع مشترك الموقع الإلكتروني رسوم الهاتف الشهرية أيضًا أبدًا.",
  "plans.priceNote": "تبلغ Essentials $14.99/شهريًا بالإضافة إلى الضرائب السارية، إن وجدت. وتبلغ Business $29.99/شهريًا بالإضافة إلى الضرائب السارية، إن وجدت. تُحدَّد أي ضريبة مطلوبة أثناء الدفع لدى المزوّد ويجب أن تظهر في المبلغ النهائي قبل الدفع. هذه الصفحة ليست عرض سعر ضريبيًا ولا إذن دفع.",
  "plans.mobilePriceNote": "تبلغ خطة الهاتف فقط $4.99/شهريًا بسعرها الأساسي المقصود في الولايات المتحدة. يعرض App Store أو Google Play سعر الاشتراك المحلي الفعلي وأي ضرائب سارية قبل الشراء. تُحدَّد حدود منتجاتها ومواقعها وموظفيها عند الإطلاق، بشكل منفصل عن فئات الموقع الإلكتروني.",
  "plans.planChangeNote": "يجب أن يؤكد مزوّد الفوترة أي تغيير في خطة الموقع الإلكتروني. وسيُشرح السعر الجديد وتاريخ السريان وأي تناسب قبل الموافقة على التغيير. يجب ألا تُنشئ الترقية اشتراكًا ثانيًا.",
  "plans.providerNote": "تتم معالجة الأسعار والرسوم والتجارب عبر المزوّد الذي تشترك من خلاله — App Store أو Google Play أو الموقع الإلكتروني أو Shopify — وليس عبر هذه الصفحة أبدًا.",
