  "settings.cancelTerms.appleLink": "تعليمات الإلغاء من Apple",
  "settings.cancelTerms.googlePlayLink": "تعليمات الإلغاء من Google Play",
  "settings.cancelTerms.graceTitle": "بعد انتهاء فترتك المدفوعة — مهلة 15 يومًا، ثم الحذف:",
  "settings.cancelTerms.intro": "هذه شروط اشتراكات Luminous StockHaven المدفوعة. تتم فوترة اشتراكات الموقع الإلكتروني عبر Stripe. ويمكنك إلغاء اشتراكك بنفسك في أي وقت باستخدام زر «إلغاء الاشتراك» أدناه — ولا حاجة إلى موافقة الموظفين. ويمكن أيضًا معالجة طلبات الإلغاء واسترداد المبالغ عبر جهة دعم العملاء الرسمية، theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "يمكنك إلغاء اشتراكك بنفسك في أي وقت. ولا يلزم موافقة الموظفين. ولا تتوقف التجديدات المستقبلية إلا بعد أن يؤكد مزوّد الفوترة الإلغاء.",
  "settings.cancelTerms.noApprovalTitle": "الإلغاء دون موافقة:",
  "settings.cancelTerms.paymentBody": "بالنسبة إلى الفترات التجريبية المدفوعة، تتطلب الفترة التجريبية التي مدتها سبعة أيام طريقة دفع عند التسجيل. وما لم يُلغَ الاشتراك خلال مهلة الإلغاء المطبقة على الفترة التجريبية، ستُخصم رسوم الخطة الشهرية المختارة تلقائيًا بعد انتهاء الفترة التجريبية. ويجب عرض السعر وتاريخ الفوترة الأول ومهلة الإلغاء الخاصة بالمزوّد أثناء التسجيل. وتتم فوترة الفترة التجريبية عبر Stripe.",
  "settings.cancelTerms.paymentTitle": "طريقة الدفع والتجديد التلقائي:",
  "settings.cancelTerms.remainingBody": "إذا كنت قد دفعت بالفعل عن فترة فوترة، يمكنك الاحتفاظ بالوصول حتى ذلك التاريخ المدفوع حتى الذي تم التحقق منه. ويتطلب الإنهاء المبكر تأكيدًا مناسبًا من المزوّد وأي معالجة استرداد مطبقة. وينتهي الوصول في الفترة التجريبية المجانية وفقًا لتاريخ إنهاء الفترة التجريبية الذي أكده المزوّد.",
  "settings.cancelTerms.remainingTitle": "الوصول المتبقي:",
  "settings.cancelTerms.storesBody": "إذا اشتركت يومًا عبر Google Play أو Apple App Store، فإن اشتراكك تُفوتره وتديره ذلك المتجر. وقد تحتاج إلى إلغائه مباشرة من قسم الاشتراكات في حساب Google أو Apple نفسه الذي استخدمته للاشتراك. ولا يؤدي إلغاء اشتراك منفصل في الموقع الإلكتروني، أو إلغاء تثبيت هذا التطبيق، أو طلب حذف حساب Luminous StockHaven إلى إلغاء اشتراك تُفوتره المتجر تلقائيًا. تحقق من إيصال الشراء لتأكيد الجهة التي تُفوترك.",
  "settings.cancelTerms.storesTitle": "اشتراكات Google Play وApple App Store (إذا اشتركت يومًا عبر متجر):",
  "settings.cancelTerms.title": "شروط وأحكام الإلغاء",
  "settings.cancelTerms.trialBody": "يمكن استخدام الفترة التجريبية التي مدتها سبعة أيام مرة واحدة فقط لكل عميل مؤهل. ولا يمنح إلغاء فترة تجريبية أو اشتراك فترة تجريبية أخرى؛ ويجب على العملاء العائدين اختيار اشتراك مدفوع.",
  "settings.cancelTerms.trialTitle": "فترة تجريبية مجانية واحدة:",
