  "payroll.dd.steps.body": "1. تحتاج إلى حساب مصرفي للعمل يمكنه إرسال مدفوعات ACH. 2. اجمع نموذج تفويض موقّعًا من كل عضو في الفريق - يساعد الشيك الملغى في التحقق من الأرقام. 3. أرسل كشوف المرتبات قبل يوم الدفع بـ 2-3 أيام عمل حتى يصل المال في الوقت المناسب. 4. تشترط معظم الولايات موافقة خطية من عضو الفريق. يجمع هذا التطبيق النماذج ويرشدك خلال الخطوات - أما إرسال المال فعليًا فيتم عبر بنكك الخاص.",
