  "settings.security.backupCodesDesc": "مفاتيح احتياطية ذات استخدام واحد. اطبعها أو اكتبها واحتفظ بها في مكان آمن — كل واحد يمكنه إعادتك مرة واحدة إذا فقدت بريدك الإلكتروني.",
