  "settings.security.codesOnceWarning": "تُعرض هذه الرموز مرة واحدة فقط — نحتفظ بنسخة مشوّشة فقط، لذا حتى نحن لا نستطيع عرضها مجددًا. إنشاء مجموعة جديدة يلغي كل رمز أقدم.",
