  "settings.security.backupEmailPending": "أرسلنا رمزًا مكوّنًا من 6 أرقام إلى ذلك العنوان. أدخله هنا لإنهاء تعيينه كبريدك الاحتياطي.",
  "settings.security.backupEmailVerified": "تم التحقق من البريد الاحتياطي: {email}",
