  "rewards.voided": "تم إبطال المكافأة.",
  "workforce.tab.rewards": "المكافآت",
  "training.lessons.mgr-give-rewards.step1": "افتح القوى العاملة واضغط على المكافآت. اختر عضو الفريق، ثم النوع: خصم نسبي في المتجر، أو بطاقة هدايا، أو شيء آخر تصفه بكلماتك الخاصة.",
  "training.lessons.mgr-give-rewards.step2": "أعطِ المكافأة اسمًا قصيرًا وملاحظة إن أردت. يحصل الشخص على جرس فورًا، وتنتظر المكافأة في مكافآتي الخاصة بها مع رمزها الخاص.",
  "training.lessons.mgr-give-rewards.step3": "الحد، بالتصميم: تكافئ الموظفين فقط. لا يمكنك مكافأة نفسك أو مدير آخر — مكافأة مدير قرار المالك، وسيرفض التطبيق ذلك بصراحة.",
  "training.lessons.mgr-give-rewards.step4": "عند الخزينة، اكتب الرمز الذي يريك إياه عضو الفريق وعلّمه كمُستخدَم — كل رمز يعمل مرة واحدة. يمكنك إبطال مكافأة منحتها إذا تغيّرت الخطط؛ هدايا المالك تخص المالك لإبطالها.",
  "training.lessons.mgr-give-rewards.title": "منح المكافآت لموظفيك",
  "training.lessons.owner-give-rewards.step1": "تعيش المكافآت في القوى العاملة، في علامة تبويب المكافآت، وهي خاصة بخطة Business فقط — على Essentials تُظهر علامة التبويب بابًا مقفلًا، حتى يرى فريقك ما تحمله الخطة الأكبر.",
  "training.lessons.owner-give-rewards.step2": "يمكنك مكافأة أي شخص في الفريق — الموظفون والمديرون على حد سواء. اختر الشخص، ثم النوع: خصم نسبي في المتجر (أي نسبة تختارها)، أو بطاقة هدايا لأي مكان، أو أي حافز تصفه بكلماتك الخاصة.",
  "training.lessons.owner-give-rewards.step3": "تهبط المكافأة برمزها الخاص ذي الاستخدام الواحد وترنّ جرس الشخص. يُظهر الرمز عند الخزينة؛ يكتب مالك أو مدير الرمز لوضع علامة كمُستخدَمة.",
  "training.lessons.owner-give-rewards.step4": "تحمل قسيمة مكافأة مطبوعة أو مشتركة اسم عملك فقط — لا اسم التطبيق أبدًا. إنها شكر متجرك، لا إعلان.",
  "training.lessons.owner-give-rewards.title": "منح المكافآت (خطة Business)",
  "training.lessons.owner-rewards-oversight.step1": "يمكن لمديرك منح المكافآت أيضًا — للموظفين فقط. يرفض التطبيق مديرًا يكافئ نفسه أو مديرًا آخر؛ مكافأة مدير قرارك دائمًا.",
  "training.lessons.owner-rewards-oversight.step2": "ترى كل مكافأة في العمل في سجل المكافآت: من منحها ومن حصل عليها وما إذا كانت جاهزة أو مُستخدَمة أو مُبطلة. يرى المدير فقط المكافآت التي منحها والتي تلقّاها.",
  "training.lessons.owner-rewards-oversight.step3": "يمكنك إبطال أي مكافأة، بما فيها واحدة منحها مديرك. يمكن للمدير إبطال هداياه الخاصة، لكن لا هداياك أبدًا.",
  "training.lessons.owner-rewards-oversight.step4": "كل رمز يعمل مرة واحدة بالضبط، ولا يمكن استخدام مكافأة مُبطلة أبدًا — يُظهر السجل دائمًا كيف انتهت مكافأة.",
  "training.lessons.owner-rewards-oversight.title": "الإشراف على المكافآت: منح مديرك",
  "training.lessons.staff-your-rewards.step1": "عندما يمنحك مديرك أو المالك مكافأة، يرنّ جرسك. افتح القوى العاملة واضغط على المكافآت لرؤيتها تحت مكافآتي.",
  "training.lessons.staff-your-rewards.step2": "لكل مكافأة رمزها الخاص. احتفظ به لنفسك — من يُظهر الرمز عند الخزينة هو من يستخدم المكافأة.",
  "training.lessons.staff-your-rewards.step3": "لاستخدامها، أظهِر الرمز عند شرائك. يكتب الشخص عند الخزينة الرمز ويعلّمه كمُستخدَم — كل رمز يعمل مرة واحدة بالضبط.",
  "training.lessons.staff-your-rewards.step4": "المكافآت متعة خاصة بخطة Business. إذا لم يكن متجرك على Business، تُظهر علامة تبويب المكافآت بابًا مقفلًا بدلًا من ذلك — تلك هي الخطة، لا خطأ.",
  "training.lessons.staff-your-rewards.title": "مكافآتك: العثور على رمزك واستخدامه",
  "training.module.rewards": "المكافآت والحوافز",
